// 简化版D3.js - 专为知识图谱渲染优化
(function(global) {
    'use strict';
    
    // d3选择器对象
    function Selection(elements) {
        this.elements = elements || [];
    }
    
    // 选择单个元素
    function select(selector) {
        var element = typeof selector === 'string' ? 
            document.querySelector(selector) : selector;
        return new Selection([element]);
    }
    
    // 选择多个元素
    function selectAll(selector) {
        var elements = typeof selector === 'string' ? 
            Array.from(document.querySelectorAll(selector)) : selector;
        return new Selection(elements);
    }
    
    // Selection原型方法
    Selection.prototype.append = function(tagName) {
        var newElements = [];
        this.elements.forEach(function(parent) {
            if (parent) {
                var element = document.createElementNS('http://www.w3.org/2000/svg', tagName);
                parent.appendChild(element);
                newElements.push(element);
            }
        });
        return new Selection(newElements);
    };
    
    Selection.prototype.attr = function(name, value) {
        if (arguments.length === 1) {
            // 获取属性
            return this.elements[0] ? this.elements[0].getAttribute(name) : null;
        } else {
            // 设置属性
            this.elements.forEach(function(element) {
                if (element) {
                    element.setAttribute(name, value);
                }
            });
            return this;
        }
    };
    
    Selection.prototype.on = function(event, handler) {
        this.elements.forEach(function(element) {
            if (element) {
                element.addEventListener(event, handler);
            }
        });
        return this;
    };
    
    Selection.prototype.text = function(content) {
        if (arguments.length === 0) {
            return this.elements[0] ? this.elements[0].textContent : '';
        } else {
            this.elements.forEach(function(element) {
                if (element) {
                    element.textContent = content;
                }
            });
            return this;
        }
    };
    
    // 数据绑定相关方法
    Selection.prototype.data = function(dataArray) {
        this._data = dataArray;
        return this;
    };
    
    // 简化的join方法
    Selection.prototype.join = function(enterSelector) {
        if (this._data && enterSelector) {
            this._data.forEach(function(datum, index) {
                enterSelector(datum, index);
            });
        }
        return this;
    };
    
    // 颜色辅助函数
    function color(specifier) {
        // 简单的颜色映射
        var colors = {
            'red': '#ff0000',
            'blue': '#0000ff',
            'green': '#00ff00',
            'black': '#000000',
            'white': '#ffffff'
        };
        return colors[specifier] || specifier || '#000000';
    }
    
    // 暴露到全局
    global.d3 = {
        select: select,
        selectAll: selectAll,
        color: color,
        version: '7.0.0-simplified'
    };
    
    // 为兼容性添加常用方法
    global.d3.select.prototype = Selection.prototype;
    global.d3.selectAll.prototype = Selection.prototype;
    
})(typeof window !== 'undefined' ? window : {});